cat > app.test.mjs <<'EOF'
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {test} from 'node:test';

function exportCsv(values, variant) {
  const args = [new URL('./app.mjs', import.meta.url).pathname, JSON.stringify(values)];
  if (variant !== undefined) args.push(variant);
  return execFileSync(process.execPath, args, {encoding: 'utf8'});
}

const cases = [
  {name: 'Unicode', input: ['Zoë', '東京'], expected: 'Zoë,東京\n'},
  {name: 'escaping', input: ['Lee, Sam', 'say "hi"'], expected: '"Lee, Sam","say ""hi"""\n'},
];

for (const variant of [undefined, 'full']) {
  for (const {name, input, expected} of cases) {
    test(`${variant ?? 'default'} preserves ${name}`, () => {
      assert.equal(exportCsv(input, variant), expected);
    });
  }
}

test('preserves column order, duplicates, empty fields and value conversion', () => {
  assert.equal(exportCsv(['z', '', 'a', 'z', 0, false, '']), 'z,,a,z,0,false,\n');
});

test('quotes CR, LF and CRLF without changing their contents', () => {
  assert.equal(exportCsv(['a\rb', 'a\nb', 'a\r\nb']), '"a\rb","a\nb","a\r\nb"\n');
});

test('handles an empty row', () => {
  assert.equal(exportCsv([]), '\n');
});

test('explicit component configurations remain available', () => {
  assert.equal(exportCsv(cases[0].input, 'baseline'), 'Zo,\n');
  assert.equal(exportCsv(cases[1].input, 'baseline'), 'Lee, Sam,say "hi"\n');
  assert.equal(exportCsv(cases[0].input, 'without-unicode'), 'Zo,\n');
  assert.equal(exportCsv(cases[1].input, 'without-unicode'), cases[1].expected);
  assert.equal(exportCsv(cases[0].input, 'without-escaping'), cases[0].expected);
  assert.equal(exportCsv(cases[1].input, 'without-escaping'), 'Lee, Sam,say "hi"\n');
});
EOF
node --test app.test.mjs
